import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
  VNode,
  Watch,
} from '@stencil/core';
import { selectMessages } from '@fe-infra/keystone-locales';
import { getPartProps, Status } from '@src/shared/base-props';
import { t } from '@src/shared/i18n';
import { ValueField } from '@src/components/ks-value-field/types';
import { SearchConfig, TreeDataNode, TreeSelectPartProps } from '../types';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import { DetailArgs } from '@src/shared/dom';
import { noop } from 'lodash-es';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';
import {
  convertDataToEntities,
  DataEntity,
  FlattenNode,
  ShowCheckedStrategy,
  Value,
  formatStrategyValues,
} from '../utils';
import { KsTooltip } from '@src/components';
import { KsIconChevronUp, KsIconSearch } from '@fe-infra/keystone-icons-stencil';

const prefix = 'tree-select';
/**
 * @slot prefix - Allows customization of the content displayed before the value field.
 * @slot suffix - Allows customization of the content displayed after the value field.
 * @part tooltip - The popover container that anchors and positions the dropdown.
 * @part popup - The popup container.
 */
@Component({
  tag: 'ks-tree-select',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTreeSelect extends FormBaseComponent<Value | Value[]> implements ComponentInterface {
  @Element() el!: HTMLKsTreeSelectElement;
  private treeViewRef!: HTMLKsTreeViewElement & { keyEntities?: Record<Value, DataEntity<TreeDataNode>> };
  private optionKeyEntities: Record<Value, DataEntity<TreeDataNode>> = {};
  get keyEntities(): Record<Value, DataEntity<TreeDataNode>> | undefined {
    return this.treeViewRef?.keyEntities || this.optionKeyEntities;
  }

  // ====== Value Field Props ======
  /** Whether the value field is clearable. */
  @Prop() clearable = false;

  /** Whether the value field is auto-focused. */
  @Prop() autoFocus = false;

  /** Whether the tags in the value field should be ellipsis when they overflow. */
  @Prop() tagsEllipsis = false;

  /** The placeholder text for the value field. */
  @Prop() placeholder = t(selectMessages.placeholder);

  /** The status of the value field. */
  @Prop() @FormContextValueReconcile() status?: Status;

  /**
   * A custom function to transform dropdown menu items into value fields tags for display. This allows you to customize how selected items are rendered in the select component. If not provided, the component will use its default transformation logic.
   *
   * Example: ``(items) => items.map(item => ({ value: item.value, label: `Custom: ${item.label}` }))``
   */
  @Prop() mapItemsToValueFields: (items: TreeDataNode[]) => ValueField[] = (items) =>
    items.map((item) => ({
      value: item.value,
      label: item.label?.toString(),
    }));

  // ====== Tree View Props ======

  /** Whether to support multiple selection. */
  @Prop() multiple = false;

  /** Whether the tree view is disabled. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;

  /** The tree view options. */
  @Prop() options: TreeDataNode[] = [];

  /** The keys of the expanded nodes. */
  @Prop() expandedKeys?: Value[];
  /** The default keys of the expanded nodes. */
  @Prop() defaultExpandedKeys?: Value[];
  /** Fired when the expanded nodes change. */
  @Event({ bubbles: false, composed: false }) ksExpand!: EventEmitter<
    DetailArgs<
      [
        Value[],
        {
          expanded: boolean;
          node: TreeDataNode;
        },
      ]
    >
  >;

  /** Whether to expand parent nodes when child nodes are expanded in the first render. */
  @Prop() defaultExpandParent = false;

  /** Whether to expand parent nodes when child nodes are expanded. */
  @Prop() autoExpandParent = false;

  /** Whether to expand all nodes by default. */
  @Prop() defaultExpandAll = false;

  /** The keys of the checked nodes. */
  @Prop() checkedKeys?: Value[] | { checkedKeys: Value[]; halfCheckedKeys: Value[] };
  @Watch('checkedKeys')
  // eslint-disable-next-line @stencil-community/no-unused-watch
  @Watch('valueFromContext')
  checkedKeysStateUpdate() {
    const formValue =
      this._provider === 'formItem' && this.checkedKeys === undefined ? this.valueFromContext : undefined;
    const mergedCheckedKeys =
      this.checkedKeys !== undefined ? this.checkedKeys : (formValue ?? this.defaultCheckedKeys);

    this.checkedKeysState = Array.isArray(mergedCheckedKeys)
      ? mergedCheckedKeys
      : typeof mergedCheckedKeys === 'object'
        ? mergedCheckedKeys.checkedKeys
        : mergedCheckedKeys !== undefined
          ? [mergedCheckedKeys]
          : [];
  }
  /** The default keys of the checked nodes. */
  @Prop() defaultCheckedKeys?: Value[] | { checkedKeys: Value[]; halfCheckedKeys: Value[] };
  /** Whether to check children nodes strictly. */
  @Prop() checkStrictly?: boolean;
  /** Fired when the checked nodes change. */
  @Event({ bubbles: false, composed: false }) ksCheck!: EventEmitter<
    DetailArgs<
      [
        Value[],
        {
          checked: boolean;
          checkedNodes: TreeDataNode[];
          halfCheckedKeys: Value[];
          node: TreeDataNode;
        },
      ]
    >
  >;
  /** Async callback used to load child nodes when a branch is expanded. */
  @Prop() loadData?: (treeNode: TreeDataNode) => Promise<void>;
  /** The keys of the loaded nodes. */
  @Prop() loadedKeys?: Value[];
  /** Whether the tree view is loading. */
  @Prop() loading = false;

  /** Fired when a node is loaded. */
  @Event({ bubbles: false, composed: false }) ksLoad!: EventEmitter<DetailArgs<[Value[], TreeDataNode]>>;

  /** Specifies if the list should enable virtualized scrolling. */
  @Prop() virtual?: boolean | { estimatedItemHeight: number | ((item: FlattenNode<TreeDataNode>) => number) } = true;

  // ====== Tree View Select Props ======

  /** Search config for the tree select. In most scenarios, you can pass `true` to enable search. For custom scenarios, you can pass a config object to customize the search behavior. */
  @Prop() search?: SearchConfig | boolean;
  /** The current value of the search input in the tree select. */
  @Prop() searchValue?: string;
  @Watch('searchValue')
  updateInternalSearchValueState(newValue?: string) {
    this.internalSearchValue = newValue || '';
  }
  @State() internalSearchValue = '';
  private internalOnSearch = ({ detail: searchText }: CustomEvent<string>) => {
    if (this.searchValue === undefined) {
      // uncontrolled
      this.internalSearchValue = searchText;
    }
    // trigger event
    this.ksSearch.emit(searchText);
  };

  /** The component that display in the suffix area */
  @Slot({ slotname: 'suffix' }) private suffixSlot?: Slots;

  /** The component that display in the prefix area */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  @State() filterTreeNode?: (node: TreeDataNode) => boolean;
  @Watch('options')
  @Watch('internalSearchValue')
  generateFilteredTreeData() {
    if (!this.internalSearchValue || !this.search) {
      this.filterTreeNode = undefined;
      return;
    }

    const filterOptionFunc: SearchConfig['filter'] =
      typeof this.search === 'object' && typeof this.search.filter === 'function'
        ? this.search.filter
        : (_, dataNode) =>
            dataNode.label?.toString().toLocaleLowerCase().includes(this.internalSearchValue.toLocaleLowerCase()) ||
            false;

    this.filterTreeNode = filterOptionFunc.bind(this, this.internalSearchValue);
  }

  @Watch('options')
  updateOptionKeyEntities() {
    this.optionKeyEntities = convertDataToEntities(this.options).keyEntities;
    this.syncDisplayValue(this.checkedKeysState, this.optionKeyEntities);
  }

  /** Indicates whether the dropdown menu is currently open. */
  @Prop() open?: boolean;
  /** Indicates whether the dropdown menu is default open. */
  @Prop() defaultOpen?: boolean;
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() internalOpenState?: boolean;

  /** The list has a default height, available for `popupHeight` to override. If `"auto"` is passed, the height will be auto-scaled. */
  @Prop() popupHeight: KsTooltip['popupHeight'] = { max: 381 };

  /** The width of the dropdown menu. */
  @Prop() popupWidth?: KsTooltip['popupWidth'] = { min: 120, value: 'matchAnchor' };

  /** The props of the tree select parts. */
  @Prop() partProps?: TreeSelectPartProps;

  /** The strategy to show checked nodes. */
  @Prop() showCheckedStrategy: ShowCheckedStrategy = 'parent';

  /** Fired when the search input value changes. */
  @Event({ bubbles: false, composed: false }) ksSearch!: EventEmitter<string>;

  /** Fired when the dropdown menu open state changes. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;

  /** Fired when the checked nodes change. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<
    DetailArgs<[Value | Value[], TreeDataNode | TreeDataNode[]]>
  >;

  @State() checkedKeysState?: Value[];

  private triggerChange(nextValues: Value[]) {
    if (this.checkedKeys === undefined) {
      this.checkedKeysState = nextValues;
    }
    if (this.multiple) {
      this.ksChange.emit(
        DetailArgs(
          nextValues,
          nextValues.map((key) => this.keyEntities?.[key]?.node as TreeDataNode),
        ),
      );
    } else {
      const value = nextValues[0] as Value;
      this.ksChange.emit(DetailArgs(value, this.keyEntities?.[value]?.node as TreeDataNode));
    }
  }

  @State() private displayValue?: ValueField[];
  @Watch('checkedKeysState')
  updateDisplayValue(nextValues?: Value[]) {
    this.syncDisplayValue(nextValues);
  }

  private syncDisplayValue(
    nextValues?: Value[],
    keyEntities: Record<Value, DataEntity<TreeDataNode>> | undefined = this.keyEntities,
  ) {
    if (!keyEntities) return;

    const items =
      nextValues?.map((key) => keyEntities[key]?.node).filter((node): node is TreeDataNode => Boolean(node)) || [];
    this.displayValue = this.mapItemsToValueFields(items);
  }

  render() {
    return (
      <Host class="KsTreeSelect">
        <ks-popover
          part="tooltip"
          class={`${prefix}__tooltip`}
          size="auto"
          trigger="click"
          disabled={this.disabled}
          open={this.internalOpenState}
          arrow={false}
          onKsOpenChange={({ detail: open }) => {
            !this.disabled && (this.internalOpenState = open);
          }}
          popupWidth={this.popupWidth}
          popupHeight={this.popupHeight}
          {...getPartProps(this, 'tooltip')}
        >
          <div slot="content" part="popup" class={`${prefix}__popup`} {...getPartProps(this, 'popup')}>
            {this.search && (
              <div class={`${prefix}__search`}>
                <ks-input value={this.internalSearchValue} onKsChange={this.internalOnSearch}>
                  <KsIconSearch size="14" slot="prefix" />
                </ks-input>
              </div>
            )}
            <ks-tree-view
              ref={(el) => (this.treeViewRef = el!)}
              multiple={this.multiple}
              disabled={this.disabled}
              options={this.options}
              expandedKeys={this.expandedKeys}
              defaultExpandedKeys={this.defaultExpandedKeys}
              defaultExpandParent={this.defaultExpandParent}
              autoExpandParent={this.autoExpandParent}
              defaultExpandAll={this.defaultExpandAll}
              checkedKeys={this.checkedKeysState}
              defaultCheckedKeys={this.defaultCheckedKeys}
              checkStrictly={this.checkStrictly}
              loadData={this.loadData}
              loadedKeys={this.loadedKeys}
              loading={this.loading}
              filterTreeNode={this.filterTreeNode}
              onKsExpand={({ detail }) => this.ksExpand.emit(detail)}
              onKsCheck={({ detail }) => {
                this.ksCheck.emit(detail);
                const checkedKeys = detail[0];
                if (this.checkedKeys === undefined) {
                  this.checkedKeysState = checkedKeys;
                }
                const nextValues = formatStrategyValues(checkedKeys, this.showCheckedStrategy, this.keyEntities || {});
                this.triggerChange(nextValues);
                if (!this.multiple) {
                  this.internalOpenState = false;
                }
              }}
              onKsLoad={({ detail }) => this.ksLoad.emit(detail)}
              virtual={this.virtual}
              wrapWithSlot={this.wrapWithSlot}
              setDynamicRenderDeps={(children, getPassThroughSlots) => {
                this.passThroughSlots = getPassThroughSlots?.() || [];
                this.setDynamicRenderDeps(children);
              }}
            >
              {this.passThroughSlots}
            </ks-tree-view>
          </div>
          <ks-value-field
            class={prefix}
            type={this.multiple ? 'tagged' : 'texted'}
            tagsEllipsis={this.tagsEllipsis}
            value={this.displayValue}
            clearable={this.clearable}
            autoFocus={this.autoFocus}
            focusElement={this.internalOpenState}
            disabled={this.disabled}
            status={this.status}
            placeholder={this.placeholder}
            enableInput={false}
            onKsChange={({ detail }) => {
              const checkedKeys = detail.map((item) => item.value);
              if (this.checkedKeys === undefined) {
                this.checkedKeysState = checkedKeys;
              }
              const nextValues = formatStrategyValues(checkedKeys, this.showCheckedStrategy, this.keyEntities || {});
              this.triggerChange(nextValues);
            }}
          >
            {this.prefixSlot && <slot slot="prefix" name="prefix" />}
            <div slot="suffix" class={`${prefix}__suffix`}>
              {this.suffixSlot && <slot name="suffix" />}
              <KsIconChevronUp
                size="14"
                class={{
                  icon: true,
                  [`icon--down`]: !this.internalOpenState,
                }}
              />
            </div>
          </ks-value-field>
        </ks-popover>
      </Host>
    );
  }

  componentWillLoad(): Promise<void> | void {
    this.updateOptionKeyEntities();
    this.generateFilteredTreeData();
    this.checkedKeysStateUpdate();
    this.syncDisplayValue(this.checkedKeysState, this.optionKeyEntities);
  }

  componentDidLoad() {
    this.updateDisplayValue(this.checkedKeysState);
  }

  /** @private Internal prop for render layer, please don't use. */
  @Prop() wrapWithSlot: (slotName: string, children: unknown) => unknown = (_slotName, children) => children;
  /** @private Internal prop for render layer, please don't use. */
  @Prop() setDynamicRenderDeps: (children: unknown[]) => void = noop;
  @State() passThroughSlots: VNode[] = [];
}
